2	import "mapbox-gl/dist/mapbox-gl.css";
3	import { useCallback, useEffect, useRef } from "react";
4	import { useFloorPlanStore } from "./floorPlanStore";
5	import { FLOORS } from "./mapData";
6	import {
7	  ASSET_RADIUS_EXPR,
8	  COLORS,
9	  EDGE_OPACITY_EXPR,
10	  EDGE_WIDTH_EXPR,
11	  LABEL_SIZE,
12	  LAYER_IDS,
13	  MAP_STYLE,
14	  SOURCE_IDS,
15	  STATUS_COLOR_EXPR,
16	  ZONE_FILL_EXPR,
17	  ZONE_LABEL_COLOR_EXPR,
18	  ZONE_OUTLINE_EXPR,
19	} from "./mapStyles";
20	import {
21	  buildAssetsGeoJSON,
22	  buildEdgesGeoJSON,
23	  buildZonesGeoJSON,
24	  facilityBounds,
25	  facilityCenter,
26	} from "./mapUtils";
27	
28	const TOKEN = import.meta.env.VITE_MAPBOX_TOKEN as string | undefined;
29	
30	export default function AtlasFloorPlanMap() {
31	  const containerRef = useRef<HTMLDivElement>(null);
32	  const mapRef = useRef<mapboxgl.Map | null>(null);
33	  const mapLoadedRef = useRef(false);
34	
35	  const activeFloorId = useFloorPlanStore((s) => s.activeFloorId);
36	  const selectedAssetId = useFloorPlanStore((s) => s.selectedAssetId);
37	  const incidentAssetOverrides = useFloorPlanStore((s) => s.incidentAssetOverrides);
38	  const incidentEdgeOverrides = useFloorPlanStore((s) => s.incidentEdgeOverrides);
39	  const layerVisibility = useFloorPlanStore((s) => s.layerVisibility);
40	
41	  // Refresh GeoJSON sources from current store state
42	  const refreshSources = useCallback(() => {
43	    const map = mapRef.current;
44	    if (!map || !mapLoadedRef.current) return;
45	    const floor = FLOORS[activeFloorId];
46	    (map.getSource(SOURCE_IDS.zones) as mapboxgl.GeoJSONSource | undefined)?.setData(
47	      buildZonesGeoJSON(floor.zones)
48	    );
49	    (map.getSource(SOURCE_IDS.assets) as mapboxgl.GeoJSONSource | undefined)?.setData(
50	      buildAssetsGeoJSON(floor.assets, selectedAssetId, incidentAssetOverrides)
51	    );
52	    (map.getSource(SOURCE_IDS.edges) as mapboxgl.GeoJSONSource | undefined)?.setData(
53	      buildEdgesGeoJSON(floor.edges, floor.assets, incidentEdgeOverrides)
54	    );
55	  }, [activeFloorId, selectedAssetId, incidentAssetOverrides, incidentEdgeOverrides]);
56	
57	  // Re-run when any data changes; when floor changes also fit the camera
58	  const prevFloorRef = useRef(activeFloorId);
59	  useEffect(() => {
60	    refreshSources();
61	    if (activeFloorId !== prevFloorRef.current) {
62	      prevFloorRef.current = activeFloorId;
63	      if (mapRef.current && mapLoadedRef.current) {
64	        mapRef.current.fitBounds(facilityBounds(), { padding: 30, duration: 600 });
65	      }
66	    }
67	  }, [refreshSources, activeFloorId]);
68	
69	  // Layer visibility
70	  useEffect(() => {
71	    const map = mapRef.current;
72	    if (!map || !mapLoadedRef.current) return;
73	
74	    const setVis = (id: string, visible: boolean) => {
75	      if (map.getLayer(id)) map.setLayoutProperty(id, "visibility", visible ? "visible" : "none");
76	    };
77	
78	    setVis(LAYER_IDS.edgesPower, layerVisibility.power);
79	    setVis(LAYER_IDS.edgesCooling, layerVisibility.cooling);
80	    setVis(LAYER_IDS.edgesNetwork, layerVisibility.network);
81	    setVis(LAYER_IDS.edgesDependency, layerVisibility.dependency);
82	    setVis(LAYER_IDS.assetsLabels, layerVisibility.labels);
83	
84	    const edgeLayers = [
85	      LAYER_IDS.edgesPower,
86	      LAYER_IDS.edgesCooling,
87	      LAYER_IDS.edgesNetwork,
88	      LAYER_IDS.edgesDependency,
89	    ];
90	
91	    if (layerVisibility.criticalPathOnly) {
92	      for (const lid of edgeLayers) {
93	        if (map.getLayer(lid)) map.setFilter(lid, ["==", ["get", "activeInIncident"], 1]);
94	      }
95	    } else {
96	      const resourceMap: Record<string, string> = {
97	        [LAYER_IDS.edgesPower]: "power",
98	        [LAYER_IDS.edgesCooling]: "cooling",
99	        [LAYER_IDS.edgesNetwork]: "network",
100	        [LAYER_IDS.edgesDependency]: "dependency",
101	      };
102	      for (const lid of edgeLayers) {
103	        if (map.getLayer(lid)) map.setFilter(lid, ["==", ["get", "resource"], resourceMap[lid]]);
104	      }
105	    }
106	  }, [layerVisibility]);
107	
108	  // Initialize map once on mount; empty dep array is intentional
109	  useEffect(() => {
110	    if (!containerRef.current || mapRef.current || !TOKEN) return;
111	
112	    mapboxgl.accessToken = TOKEN;
113	
114	    const map = new mapboxgl.Map({
115	      container: containerRef.current,
116	      style: MAP_STYLE,
117	      center: facilityCenter(),
118	      zoom: 14,
119	      minZoom: 12,
120	      maxZoom: 19,
121	      maxBounds: [
122	        facilityBounds()[0].map((v, i) => v - (i === 0 ? 0.001 : 0.001)) as [number, number],
123	        facilityBounds()[1].map((v, i) => v + (i === 0 ? 0.001 : 0.001)) as [number, number],
124	      ],
125	      attributionControl: false,
126	      logoPosition: "bottom-right",
127	    });
128	
129	    mapRef.current = map;
130	
131	    map.on("load", () => {
132	      mapLoadedRef.current = true;
133	
134	      // Read initial floor data
135	      const initialFloor = FLOORS[useFloorPlanStore.getState().activeFloorId];
136	
137	      // ── Sources ──────────────────────────────────────────────────────────────
138	      map.addSource(SOURCE_IDS.zones, {
139	        type: "geojson",
140	        data: buildZonesGeoJSON(initialFloor.zones),
141	      });
142	      map.addSource(SOURCE_IDS.edges, {
143	        type: "geojson",
144	        data: buildEdgesGeoJSON(initialFloor.edges, initialFloor.assets, {}),
145	      });
146	      map.addSource(SOURCE_IDS.assets, {
147	        type: "geojson",
148	        data: buildAssetsGeoJSON(initialFloor.assets, null, {}),
149	      });
150	
151	      // ── Zone fill ──────────────────────────────────────────────────────────
152	      map.addLayer({
153	        id: LAYER_IDS.zonesFill,
154	        type: "fill",
155	        source: SOURCE_IDS.zones,
156	        paint: {
157	          "fill-color": ZONE_FILL_EXPR,
158	          "fill-opacity": 1,
159	        },
160	      });
161	
162	      // ── Zone outlines ──────────────────────────────────────────────────────
163	      map.addLayer({
164	        id: LAYER_IDS.zonesOutline,
165	        type: "line",
166	        source: SOURCE_IDS.zones,
167	        paint: {
168	          "line-color": ZONE_OUTLINE_EXPR,
169	          "line-width": [
170	            "match",
171	            ["get", "zoneType"],
172	            "hall",
173	            1.5,
174	            "row",
175	            1,
176	            "corridor",
177	            0.5,
178	            1,
179	          ] as mapboxgl.ExpressionSpecification,
180	          "line-dasharray": [
181	            "case",
182	            ["==", ["get", "zoneType"], "restricted"],
183	            ["literal", [4, 3]],
184	            ["literal", [1]],
185	          ] as unknown as mapboxgl.ExpressionSpecification,
186	        },
187	      });
188	
189	      // ── Zone labels ────────────────────────────────────────────────────────
190	      map.addLayer({
191	        id: LAYER_IDS.zoneLabels,
192	        type: "symbol",
193	        source: SOURCE_IDS.zones,
194	        filter: ["!in", ["get", "zoneType"], ["literal", ["corridor", "hall"]]],
195	        layout: {
196	          "text-field": ["get", "name"],
197	          "text-size": 9,
198	          "text-anchor": "top-left",
199	          "text-offset": [0.5, 0.5],
200	          "text-font": ["literal", ["Open Sans Regular"]],
201	        },
202	        paint: {
203	          "text-color": ZONE_LABEL_COLOR_EXPR,
204	          "text-halo-color": "#05070A",
205	          "text-halo-width": 1,
206	        },
207	      });
208	
209	      // ── Dependency edge layers ─────────────────────────────────────────────
210	      const edgeLayerDefs: [string, string, string][] = [
211	        [LAYER_IDS.edgesPower, "power", COLORS.power],
212	        [LAYER_IDS.edgesCooling, "cooling", COLORS.cooling],
213	        [LAYER_IDS.edgesNetwork, "network", COLORS.network],
214	        [LAYER_IDS.edgesDependency, "dependency", COLORS.dependency],
215	      ];
216	
217	      for (const [layerId, resource, color] of edgeLayerDefs) {
218	        map.addLayer({
219	          id: layerId,
220	          type: "line",
221	          source: SOURCE_IDS.edges,
222	          filter: ["==", ["get", "resource"], resource],
223	          layout: { "line-cap": "round", "line-join": "round" },
224	          paint: {
225	            "line-color": [
226	              "case",
227	              ["==", ["get", "activeInIncident"], 1],
228	              resource === "cooling" ? "#7DD3FC" : color,
229	              color,
230	            ],
231	            "line-opacity": EDGE_OPACITY_EXPR,
232	            "line-width": EDGE_WIDTH_EXPR,
233	            "line-dasharray":
234	              resource === "network"
235	                ? (["literal", [3, 2]] as unknown as mapboxgl.ExpressionSpecification)
236	                : (["literal", [1]] as unknown as mapboxgl.ExpressionSpecification),
237	          },
238	        });
239	      }
240	
241	      // Apply initial layer visibility from store
242	      const vis = useFloorPlanStore.getState().layerVisibility;
243	      if (!vis.dependency && map.getLayer(LAYER_IDS.edgesDependency)) {
244	        map.setLayoutProperty(LAYER_IDS.edgesDependency, "visibility", "none");
245	      }
246	
247	      // ── Asset circles ──────────────────────────────────────────────────────
248	      map.addLayer({
249	        id: LAYER_IDS.assetsBase,
250	        type: "circle",
251	        source: SOURCE_IDS.assets,
252	        paint: {
253	          "circle-color": STATUS_COLOR_EXPR,
254	          "circle-radius": ASSET_RADIUS_EXPR,
255	          "circle-opacity": ["case", ["==", ["get", "status"], "offline"], 0.4, 0.9],
256	          "circle-stroke-width": [
257	            "case",
258	            ["==", ["get", "status"], "critical"],
259	            2,
260	            ["==", ["get", "status"], "warning"],
261	            1.5,
262	            0.5,
263	          ] as mapboxgl.ExpressionSpecification,
264	          "circle-stroke-color": [
265	            "case",
266	            ["==", ["get", "status"], "critical"],
267	            "rgba(239,68,68,0.6)",
268	            ["==", ["get", "status"], "warning"],
269	            "rgba(245,158,11,0.5)",
270	            "rgba(255,255,255,0.08)",
271	          ] as mapboxgl.ExpressionSpecification,
272	        },
273	      });
274	
275	      // ── Selected ring ──────────────────────────────────────────────────────
276	      map.addLayer({
277	        id: LAYER_IDS.assetsSelectedRing,
278	        type: "circle",
279	        source: SOURCE_IDS.assets,
280	        filter: ["==", ["get", "selected"], 1],
281	        paint: {
282	          "circle-color": "transparent",
283	          "circle-radius": [
284	            "case",
285	            ["==", ["get", "assetType"], "crac"],
286	            15,
287	            ["==", ["get", "assetType"], "chiller"],
288	            15,
289	            ["==", ["get", "assetType"], "ups"],
290	            14,
291	            13,
292	          ] as mapboxgl.ExpressionSpecification,
293	          "circle-stroke-width": 1.5,
294	          "circle-stroke-color": "#F8FAFC",
295	          "circle-opacity": 0,
296	          "circle-stroke-opacity": 0.85,
297	        },
298	      });
299	
300	      // ── Hover highlight ────────────────────────────────────────────────────
301	      map.addLayer({
302	        id: LAYER_IDS.assetsHover,
303	        type: "circle",
304	        source: SOURCE_IDS.assets,
305	        filter: ["==", ["get", "id"], "__none__"],
306	        paint: {
307	          "circle-color": "transparent",
308	          "circle-radius": [
309	            "case",
310	            ["in", ["get", "assetType"], ["literal", ["crac", "chiller", "generator", "ups"]]],
311	            13,
312	            11,
313	          ] as mapboxgl.ExpressionSpecification,
314	          "circle-stroke-width": 1,
315	          "circle-stroke-color": "rgba(248,250,252,0.5)",
316	          "circle-opacity": 0,
317	          "circle-stroke-opacity": 0.7,
318	        },
319	      });
320	
321	      // ── Asset labels ───────────────────────────────────────────────────────
322	      map.addLayer({
323	        id: LAYER_IDS.assetsLabels,
324	        type: "symbol",
325	        source: SOURCE_IDS.assets,
326	        layout: {
327	          "text-field": ["get", "name"],
328	          "text-size": LABEL_SIZE,
329	          "text-anchor": "top",
330	          "text-offset": [0, 1.2],
331	          "text-font": ["literal", ["Open Sans Regular"]],
332	          "text-allow-overlap": false,
333	          "text-ignore-placement": false,
334	        },
335	        paint: {
336	          "text-color": [
337	            "case",
338	            ["==", ["get", "status"], "critical"],
339	            COLORS.critical,
340	            ["==", ["get", "status"], "warning"],
341	            COLORS.warning,
342	            "rgba(203,213,225,0.75)",
343	          ] as mapboxgl.ExpressionSpecification,
344	          "text-halo-color": "#05070A",
345	          "text-halo-width": 1.5,
346	        },
347	      });
348	
349	      // ── Interactions ───────────────────────────────────────────────────────
350	      map.on("click", LAYER_IDS.assetsBase, (e) => {
351	        if (!e.features?.length) return;
352	        const id = e.features[0].properties?.id as string;
353	        useFloorPlanStore.getState().selectAsset(id);
354	      });
355	
356	      map.on("click", (e) => {
357	        const features = map.queryRenderedFeatures(e.point, { layers: [LAYER_IDS.assetsBase] });
358	        if (!features.length) useFloorPlanStore.getState().selectAsset(null);
359	      });
360	
361	      map.on("mouseenter", LAYER_IDS.assetsBase, (e) => {
362	        map.getCanvas().style.cursor = "pointer";
363	        if (e.features?.[0]) {
364	          const id = e.features[0].properties?.id as string;
365	          useFloorPlanStore.getState().setHoveredAsset(id);
366	          if (map.getLayer(LAYER_IDS.assetsHover)) {
367	            map.setFilter(LAYER_IDS.assetsHover, ["==", ["get", "id"], id]);
368	          }
369	        }
370	      });
371	
372	      map.on("mouseleave", LAYER_IDS.assetsBase, () => {
373	        map.getCanvas().style.cursor = "";
374	        useFloorPlanStore.getState().setHoveredAsset(null);
375	        if (map.getLayer(LAYER_IDS.assetsHover)) {
376	          map.setFilter(LAYER_IDS.assetsHover, ["==", ["get", "id"], "__none__"]);
377	        }
378	      });
379	
380	      // ── Fit to facility after all layers are added ─────────────────────────
381	      map.fitBounds(facilityBounds(), { padding: 30, animate: false });
382	    });
383	
384	    return () => {
385	      mapLoadedRef.current = false;
386	      map.remove();
387	      mapRef.current = null;
388	    };
389	  }, []); // eslint-disable-line react-hooks/exhaustive-deps
390	
391	  if (!TOKEN) {
392	    return (
393	      <div className="flex flex-col items-center justify-center h-full bg-[#05070A] text-center px-6">
394	        <div className="w-10 h-10 rounded-xl bg-amber-500/10 border border-amber-500/30 flex items-center justify-center mb-4">
395	          <span className="text-amber-400 text-xl font-bold">!</span>
396	        </div>
397	        <p className="text-[13px] font-semibold text-zinc-300 mb-1">Mapbox token missing</p>
398	        <p className="text-[11px] text-zinc-600 max-w-xs leading-relaxed">
399	          Set{" "}
400	          <code className="text-amber-400 font-mono bg-amber-500/10 px-1 rounded">
401	            VITE_MAPBOX_TOKEN
402	          </code>{" "}
403	          in your <code className="font-mono">.env</code> file to enable the floor plan view.
404	        </p>
405	      </div>
406	    );
407	  }
408	
409	  return <div ref={containerRef} className="w-full h-full" />;
410	}
