1	import type { GeoJSON } from "geojson";
2	import type { Asset, DependencyEdge, Zone } from "./mapTypes";
3	
4	// Facility coordinate space: 200 × 100 units
5	// Maps to a small synthetic lng/lat region (no real-world geography)
6	const ORIGIN_LNG = 23.7275;
7	const ORIGIN_LAT = 37.9838;
8	const SCALE = 0.000018;
9	
10	export function facilityToLngLat(x: number, y: number): [number, number] {
11	  return [ORIGIN_LNG + x * SCALE, ORIGIN_LAT + y * SCALE];
12	}
13	
14	// Bounds with padding so perimeter walls are always visible
15	export function facilityBounds(): [[number, number], [number, number]] {
16	  return [facilityToLngLat(-15, -12), facilityToLngLat(215, 112)];
17	}
18	
19	export function facilityCenter(): [number, number] {
20	  return facilityToLngLat(100, 50);
21	}
22	
23	// Build GeoJSON FeatureCollection for zones
24	export function buildZonesGeoJSON(zones: Zone[]): GeoJSON.FeatureCollection {
25	  return {
26	    type: "FeatureCollection",
27	    features: zones.map((z) => ({
28	      type: "Feature",
29	      id: z.id,
30	      properties: {
31	        id: z.id,
32	        name: z.name,
33	        zoneType: z.type,
34	      },
35	      geometry: {
36	        type: "Polygon",
37	        coordinates: [z.polygon.map(([x, y]) => facilityToLngLat(x, y))],
38	      },
39	    })),
40	  };
41	}
42	
43	// Build GeoJSON FeatureCollection for assets
44	export function buildAssetsGeoJSON(
45	  assets: Asset[],
46	  selectedId: string | null,
47	  overrides: Record<string, string>
48	): GeoJSON.FeatureCollection {
49	  return {
50	    type: "FeatureCollection",
51	    features: assets.map((a) => {
52	      const status = overrides[a.id] ?? a.status;
53	      return {
54	        type: "Feature",
55	        id: a.id,
56	        properties: {
57	          id: a.id,
58	          name: a.name,
59	          assetType: a.type,
60	          status,
61	          criticality: a.criticality,
62	          zoneId: a.zoneId,
63	          selected: a.id === selectedId ? 1 : 0,
64	        },
65	        geometry: {
66	          type: "Point",
67	          coordinates: facilityToLngLat(...a.coordinates),
68	        },
69	      };
70	    }),
71	  };
72	}
73	
74	// Build GeoJSON FeatureCollection for edges
75	// Edges that reference assets not in the provided list are silently skipped
76	// (this handles cross-floor edges naturally)
77	export function buildEdgesGeoJSON(
78	  edges: DependencyEdge[],
79	  assets: Asset[],
80	  edgeOverrides: Record<string, boolean>
81	): GeoJSON.FeatureCollection {
82	  const assetMap = new Map(assets.map((a) => [a.id, a]));
83	
84	  return {
85	    type: "FeatureCollection",
86	    features: edges.flatMap((e) => {
87	      const src = assetMap.get(e.sourceAssetId);
88	      const tgt = assetMap.get(e.targetAssetId);
89	      if (!src || !tgt) return [];
90	
91	      const active = edgeOverrides[e.id] ?? e.activeInIncident;
92	
93	      return [
94	        {
95	          type: "Feature" as const,
96	          id: e.id,
97	          properties: {
98	            id: e.id,
99	            resource: e.resource,
100	            edgeType: e.type,
101	            criticality: e.criticality,
102	            activeInIncident: active ? 1 : 0,
103	            minutesToImpact: e.minutesToImpact ?? -1,
104	          },
105	          geometry: {
106	            type: "LineString" as const,
107	            coordinates: [
108	              facilityToLngLat(...src.coordinates),
109	              facilityToLngLat(...tgt.coordinates),
110	            ],
111	          },
112	        },
113	      ];
114	    }),
115	  };
116	}
117	
118	export function getAssetById(assets: Asset[], id: string): Asset | undefined {
119	  return assets.find((a) => a.id === id);
120	}
121	
122	export function getUpstreamDeps(edges: DependencyEdge[], assetId: string): DependencyEdge[] {
123	  return edges.filter((e) => e.targetAssetId === assetId);
