import { Html, OrbitControls } from "@react-three/drei";
import { useCallback, useMemo } from "react";
import * as THREE from "three";
import { useFloorPlanStore } from "../atlas-map/floorPlanStore";
import { FLOORS } from "../atlas-map/mapData";
import { FLOOR_META } from "../atlas-map/mapTypes";
import type { FloorId } from "../atlas-map/mapTypes";

const SCALE = 0.14;
const FLOOR_THICKNESS = 0.18;

// Floor Y positions (bottom to top: basement → ground → upper)
const FLOOR_Y: Record<FloorId, number> = {
  "floor-c": -8,
  "floor-b": 0,
  "floor-a": 8,
};

// Zone type → fill color
const ZONE_COLORS: Record<string, string> = {
  hall: "#0d1117",
  row: "#0f1f2e",
  electrical: "#1c1000",
  cooling: "#001a2e",
  corridor: "#111111",
  network: "#14002e",
  noc: "#001a14",
  ups_room: "#1a0a00",
  patch_bay: "#0a0a1a",
  generator: "#1a0d00",
  chiller_plant: "#001a22",
  battery_room: "#1a1000",
  switchgear: "#0d0d1a",
  restricted: "#1a0000",
};

const ZONE_BORDER_COLORS: Record<string, string> = {
  hall: "#1a2030",
  row: "#1e3a5f",
  electrical: "#5c3a00",
  cooling: "#0c4a6e",
  corridor: "#1a1a1a",
  network: "#2e1065",
  noc: "#065f46",
  ups_room: "#451a03",
  patch_bay: "#1e3a5f",
  generator: "#78350f",
  chiller_plant: "#0c4a6e",
  battery_room: "#451a03",
  switchgear: "#1e3a5f",
  restricted: "#7f1d1d",
};

const STATUS_COLORS: Record<string, string> = {
  normal: "#10b981",
  warning: "#f59e0b",
  critical: "#ef4444",
  offline: "#374151",
};

function facilityToThree(x: number, y: number): [number, number] {
  return [(x - 100) * SCALE, (y - 50) * SCALE];
}

// Build a flat extruded shape from polygon points (skip closing point)
function buildZoneShape(polygon: [number, number][]): THREE.Shape {
  const pts = polygon.slice(0, -1);
  const shape = new THREE.Shape();
  const [startX, startZ] = facilityToThree(pts[0][0], pts[0][1]);
  shape.moveTo(startX, startZ);
  for (let i = 1; i < pts.length; i++) {
    const [px, pz] = facilityToThree(pts[i][0], pts[i][1]);
    shape.lineTo(px, pz);
  }
  shape.closePath();
  return shape;
}

interface FloorSlabProps {
  floorId: FloorId;
  isActive: boolean;
  onClick: () => void;
}

function FloorSlab({ floorId, isActive, onClick }: FloorSlabProps) {
  const floorData = FLOORS[floorId];
  const meta = FLOOR_META[floorId];
  const yBase = FLOOR_Y[floorId];
  const opacity = isActive ? 1 : 0.32;

  const zoneGeometries = useMemo(
    () =>
      floorData.zones.map((zone) => {
        const shape = buildZoneShape(zone.polygon);
        const geo = new THREE.ShapeGeometry(shape);
        return { zone, geo };
      }),
    [floorData.zones]
  );

  const zoneEdgeGeometries = useMemo(
    () =>
      floorData.zones.map((zone) => {
        const pts = zone.polygon.slice(0, -1);
        const positions: number[] = [];
        for (let i = 0; i < pts.length; i++) {
          const [ax, az] = facilityToThree(pts[i][0], pts[i][1]);
          const [bx, bz] = facilityToThree(pts[(i + 1) % pts.length][0], pts[(i + 1) % pts.length][1]);
          positions.push(ax, 0, az, bx, 0, bz);
        }
        const geo = new THREE.BufferGeometry();
        geo.setAttribute("position", new THREE.Float32BufferAttribute(positions, 3));
        return { zone, geo };
      }),
    [floorData.zones]
  );

  // Base slab (slightly below zones)
  const slabShape = useMemo(() => {
    const hw = 100 * SCALE + 0.3;
    const hd = 50 * SCALE + 0.3;
    const s = new THREE.Shape();
    s.moveTo(-hw, -hd);
    s.lineTo(hw, -hd);
    s.lineTo(hw, hd);
    s.lineTo(-hw, hd);
    s.closePath();
    return s;
  }, []);

  const slabGeo = useMemo(
    () =>
      new THREE.ExtrudeGeometry(slabShape, {
        depth: FLOOR_THICKNESS,
        bevelEnabled: false,
      }),
    [slabShape]
  );

  // Border lines around slab perimeter
  const borderGeo = useMemo(() => {
    const hw = 100 * SCALE + 0.3;
    const hd = 50 * SCALE + 0.3;
    const pts = [
      [-hw, 0, -hd],
      [hw, 0, -hd],
      [hw, 0, hd],
      [-hw, 0, hd],
      [-hw, 0, -hd],
    ].flat();
    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.Float32BufferAttribute(pts, 3));
    return geo;
  }, []);

  const borderColor = isActive ? "#3b82f6" : "#1e293b";
  const borderOpacity = isActive ? 0.8 : 0.4;

  return (
    <group position={[0, yBase, 0]} onClick={onClick}>
      {/* Base slab — rendered rotated so XZ is the floor plane */}
      <mesh
        geometry={slabGeo}
        rotation={[-Math.PI / 2, 0, 0]}
        position={[0, -FLOOR_THICKNESS, 0]}
      >
        <meshBasicMaterial
          color="#050709"
          transparent
          opacity={opacity * 0.95}
          side={THREE.FrontSide}
        />
      </mesh>

      {/* Zone fills */}
      {zoneGeometries.map(({ zone, geo }) => (
        <mesh
          key={zone.id}
          geometry={geo}
          rotation={[-Math.PI / 2, 0, 0]}
          position={[0, 0.002, 0]}
        >
          <meshBasicMaterial
            color={ZONE_COLORS[zone.type] ?? "#0d1117"}
            transparent
            opacity={opacity * 0.9}
            depthWrite={false}
            side={THREE.FrontSide}
          />
        </mesh>
      ))}

      {/* Zone borders */}
      {zoneEdgeGeometries.map(({ zone, geo }) => (
        <lineSegments key={`edge-${zone.id}`} geometry={geo} position={[0, 0.005, 0]}>
          <lineBasicMaterial
            color={ZONE_BORDER_COLORS[zone.type] ?? "#1e293b"}
            transparent
            opacity={opacity * 0.7}
          />
        </lineSegments>
      ))}

      {/* Assets */}
      {floorData.assets.map((asset) => {
        const [ax, az] = facilityToThree(asset.coordinates[0], asset.coordinates[1]);
        const color = STATUS_COLORS[asset.status] ?? STATUS_COLORS.normal;
        const radius =
          asset.type === "rack" ? 0.08 : asset.type === "crac" || asset.type === "chiller" ? 0.14 : 0.1;
        return (
          <mesh key={asset.id} position={[ax, 0.06, az]}>
            <sphereGeometry args={[radius, 6, 6]} />
            <meshBasicMaterial color={color} transparent opacity={opacity} />
          </mesh>
        );
      })}

      {/* Perimeter border line */}
      <lineStrip geo={borderGeo} color={borderColor} opacity={borderOpacity} />

      {/* Floor label */}
      <Html
        position={[-(100 * SCALE + 0.6), 0.3, -(50 * SCALE + 0.1)]}
        style={{ pointerEvents: "none" }}
      >
        <div
          style={{
            fontFamily: "monospace",
            fontSize: isActive ? "11px" : "9px",
            fontWeight: 700,
            letterSpacing: "0.1em",
            color: isActive ? "#f8fafc" : "#475569",
            whiteSpace: "nowrap",
            userSelect: "none",
            transition: "all 0.3s ease",
          }}
        >
          {meta.shortLabel} · {meta.description.split("—")[0].trim()}
        </div>
      </Html>
    </group>
  );
}

// Helper component for border lines
function lineStrip({
  geo,
  color,
  opacity,
}: {
  geo: THREE.BufferGeometry;
  color: string;
  opacity: number;
}) {
  return (
    <line geometry={geo}>
      <lineBasicMaterial color={color} transparent opacity={opacity} />
    </line>
  );
}

// Vertical connector lines between floors (drawn at corners)
function FloorConnectors() {
  const geo = useMemo(() => {
    const hw = 100 * SCALE + 0.3;
    const hd = 50 * SCALE + 0.3;
    const corners: [number, number][] = [
      [-hw, -hd],
      [hw, -hd],
      [hw, hd],
      [-hw, hd],
    ];
    const yTop = FLOOR_Y["floor-a"] + FLOOR_THICKNESS;
    const yBot = FLOOR_Y["floor-c"] - FLOOR_THICKNESS;
    const pts: number[] = [];
    for (const [cx, cz] of corners) {
      pts.push(cx, yTop, cz, cx, yBot, cz);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute("position", new THREE.Float32BufferAttribute(pts, 3));
    return g;
  }, []);

  return (
    <lineSegments geometry={geo}>
      <lineBasicMaterial color="#1e293b" transparent opacity={0.25} />
    </lineSegments>
  );
}

export function FloorStackScene() {
  const { activeFloorId, setFloor } = useFloorPlanStore();

  const handleFloorClick = useCallback(
    (id: FloorId) => {
      setFloor(id);
    },
    [setFloor]
  );

  return (
    <>
      {/* Ambient + directional */}
      <ambientLight intensity={0.6} />
      <directionalLight position={[10, 20, 10]} intensity={0.4} />

      <OrbitControls
        enablePan
        enableZoom
        enableRotate
        minDistance={8}
        maxDistance={60}
        makeDefault
      />

      {/* Three floor slabs */}
      {(["floor-c", "floor-b", "floor-a"] as FloorId[]).map((id) => (
        <FloorSlab
          key={id}
          floorId={id}
          isActive={activeFloorId === id}
          onClick={() => handleFloorClick(id)}
        />
      ))}

      {/* Corner connectors */}
      <FloorConnectors />
    </>
  );
}

