import { useSearchParams } from "react-router-dom";
import { CommandCenter3D } from "../../components/atlas-3d/CommandCenter3D";
import CommandCenterShell from "../../components/atlas-map/CommandCenterShell";

type FacilityViewMode = "plan" | "3d";

function ViewModeSwitcher({
  mode,
  onChange,
}: {
  mode: FacilityViewMode;
  onChange: (mode: FacilityViewMode) => void;
}) {
  return (
    <div className="flex items-center gap-1 rounded-lg border border-white/[0.08] bg-black/50 p-1 backdrop-blur-md">
      {[
        { id: "plan", label: "2.5D" },
        { id: "3d", label: "3D" },
      ].map((option) => {
        const active = mode === option.id;
        return (
          <button
            key={option.id}
            type="button"
            onClick={() => onChange(option.id as FacilityViewMode)}
            className={`rounded-md px-2 py-1 text-[10px] font-semibold tracking-wide transition-colors ${
              active
                ? "bg-white/[0.12] text-white"
                : "text-zinc-500 hover:bg-white/[0.04] hover:text-zinc-300"
            }`}
            aria-pressed={active}
          >
            {option.label}
          </button>
        );
      })}
    </div>
  );
}

export default function FloorPlan() {
  const [searchParams, setSearchParams] = useSearchParams();
  const mode: FacilityViewMode = searchParams.get("view") === "3d" ? "3d" : "plan";

  const setMode = (nextMode: FacilityViewMode) => {
    const nextParams = new URLSearchParams(searchParams);
    if (nextMode === "plan") {
      nextParams.delete("view");
    } else {
      nextParams.set("view", nextMode);
    }
    setSearchParams(nextParams, { replace: true });
  };

  const modeSwitcher = <ViewModeSwitcher mode={mode} onChange={setMode} />;

  if (mode === "3d") {
    return <CommandCenter3D modeSwitcher={modeSwitcher} />;
  }

  return <CommandCenterShell modeSwitcher={modeSwitcher} />;
}

