1	import { create } from "zustand";
2	import { CRAC07_BLAST_RADIUS, CRAC07_INCIDENT_EDGES, SCENE_ASSETS } from "./sceneData";
3	import type {
4	  AssetStatus,
5	  BlastRadiusItem,
6	  CameraFocusRequest,
7	  TimelineEvent,
8	  ViewMode,
9	  VisibleLayers,
10	} from "./sceneTypes";
11	import { formatTimestamp } from "./sceneUtils";
12	
13	type State = {
14	  selectedAssetId: string | null;
15	  hoveredAssetId: string | null;
16	  viewMode: ViewMode;
17	  activeIncidentId: string | null;
18	  assetStatuses: Record<string, AssetStatus>;
19	  activeEdgeIds: string[];
20	  visibleLayers: VisibleLayers;
21	  timelineEvents: TimelineEvent[];
22	  blastRadiusItems: BlastRadiusItem[];
23	  cameraFocusRequest: CameraFocusRequest | null;
24	};
25	
26	type Actions = {
27	  selectAsset: (id: string | null) => void;
28	  hoverAsset: (id: string | null) => void;
29	  setViewMode: (mode: ViewMode) => void;
30	  simulateCRAC07Failure: () => void;
31	  resetSimulation: () => void;
32	  toggleLayer: (layer: keyof VisibleLayers) => void;
33	  clearCameraRequest: () => void;
34	  requestCameraFocus: (req: CameraFocusRequest) => void;
35	};
36	
37	const defaultStatuses = (): Record<string, AssetStatus> =>
38	  Object.fromEntries(SCENE_ASSETS.map((a) => [a.id, a.status]));
39	
40	const DEFAULT_LAYERS: VisibleLayers = {
41	  power: true,
42	  cooling: true,
43	  network: true,
44	  dependency: true,
45	  labels: true,
46	  criticalPathOnly: false,
47	  grid: true,
48	  zoneBoundaries: true,
49	};
50	
51	let _incidentTimers: ReturnType<typeof setTimeout>[] = [];
52	
53	export const useCommandCenterStore = create<State & Actions>((set, _get) => ({
54	  selectedAssetId: null,
55	  hoveredAssetId: null,
56	  viewMode: "overview",
57	  activeIncidentId: null,
58	  assetStatuses: defaultStatuses(),
59	  activeEdgeIds: [],
60	  visibleLayers: DEFAULT_LAYERS,
61	  timelineEvents: [],
62	  blastRadiusItems: [],
63	  cameraFocusRequest: null,
64	
65	  selectAsset: (id) => set({ selectedAssetId: id }),
66	  hoverAsset: (id) => set({ hoveredAssetId: id }),
67	  setViewMode: (mode) => set({ viewMode: mode }),
68	
69	  requestCameraFocus: (req) => set({ cameraFocusRequest: req }),
70	  clearCameraRequest: () => set({ cameraFocusRequest: null }),
71	
72	  toggleLayer: (layer) =>
73	    set((s) => ({
74	      visibleLayers: { ...s.visibleLayers, [layer]: !s.visibleLayers[layer] },
75	    })),
76	
77	  simulateCRAC07Failure: () => {
78	    _incidentTimers.forEach(clearTimeout);
79	    _incidentTimers = [];
80	
81	    const affectedRackIds = CRAC07_BLAST_RADIUS.map((b) => b.assetId);
82	    const now = new Date();
83	
84	    // Step 1: flag CRAC-07
85	    set((s) => ({
86	      viewMode: "incident",
87	      activeIncidentId: "crac07-failure",
88	      selectedAssetId: "crac-07",
89	      assetStatuses: { ...s.assetStatuses, "crac-07": "critical" },
90	      activeEdgeIds: CRAC07_INCIDENT_EDGES,
91	      blastRadiusItems: CRAC07_BLAST_RADIUS,
92	      timelineEvents: [
93	        {
94	          id: "evt-1",
95	          timestamp: formatTimestamp(now),
96	          message: "Sentinel flagged CRAC-07 thermal anomaly — compressor EFF at 12%",
97	          severity: "critical",
98	        },
99	      ],
100	      cameraFocusRequest: {
101	        type: "incident",
102	        rootAssetId: "crac-07",
103	        affectedAssetIds: affectedRackIds,
104	      },
105	    }));
106	
107	    // Step 2: blast radius computed
108	    _incidentTimers.push(
109	      setTimeout(() => {
110	        set((s) => ({
111	          timelineEvents: [
112	            ...s.timelineEvents,
113	            {
114	              id: "evt-2",
115	              timestamp: formatTimestamp(new Date()),
116	              message: "Blast radius computed — 6 racks in Row C at risk",
117	              severity: "warning",
118	            },
119	          ],
120	        }));
121	      }, 900)
122	    );
123	
124	    // Step 3: first racks go warning
125	    _incidentTimers.push(
126	      setTimeout(() => {
127	        set((s) => ({
128	          assetStatuses: {
129	            ...s.assetStatuses,
130	            "rack-c12": "warning",
131	            "rack-c13": "warning",
132	            "sensor-c1": "warning",
133	            "sensor-c2": "warning",
134	          },
135	          timelineEvents: [
136	            ...s.timelineEvents,
137	            {
138	              id: "evt-3",
139	              timestamp: formatTimestamp(new Date()),
140	              message: "Rack C12, C13 marked WARNING — inlet temp rising",
141	              severity: "warning",
142	            },
143	          ],
144	        }));
145	      }, 1800)
146	    );
147	
148	    // Step 4: rack-c14 goes critical
149	    _incidentTimers.push(
150	      setTimeout(() => {
151	        set((s) => ({
152	          assetStatuses: {
153	            ...s.assetStatuses,
154	            "rack-c14": "critical",
155	            "rack-c15": "warning",
156	          },
157	          timelineEvents: [
158	            ...s.timelineEvents,
159	            {
160	              id: "evt-4",
161	              timestamp: formatTimestamp(new Date()),
162	              message: "Rack C14 marked CRITICAL — thermal throttle imminent",
163	              severity: "critical",
164	            },
165	          ],
166	        }));
167	      }, 2800)
168	    );
169	
170	    // Step 5: dispatch recommendation
171	    _incidentTimers.push(
172	      setTimeout(() => {
