await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/hall_a.png' });

// Click Hall C tab
await page.getByRole('button', { name: 'Hall C' }).click();
await page.waitForTimeout(1200);
await page.screenshot({ path: '/tmp/hall_c.png' });

await browser.close();
console.log('Done');
EOF
